create table public.occupation_roles(slug text primary key,title_en text not null,title_hi text,sector text not null,description_en text not null,description_hi text,tasks jsonb not null,skill_requirements jsonb not null,wage_min integer,wage_max integer,currency text not null default 'INR',status text not null default 'draft' check(status in ('draft','review','published','retired')),taxonomy_refs jsonb not null default '{}',updated_at timestamptz not null default now());
create table public.role_demand_snapshots(id uuid primary key default gen_random_uuid(),role_slug text not null references public.occupation_roles(slug),geography_code text not null,period_end date not null,open_role_count integer not null,growth_percent numeric,source_method text not null,unique(role_slug,geography_code,period_end));
create table public.saved_roles(user_id uuid not null references auth.users(id) on delete cascade,role_slug text not null references public.occupation_roles(slug),saved_at timestamptz not null default now(),primary key(user_id,role_slug));
alter table public.occupation_roles enable row level security;alter table public.role_demand_snapshots enable row level security;alter table public.saved_roles enable row level security;
create policy "published roles readable" on public.occupation_roles for select using(status='published' or public.is_platform_staff());create policy "demand signals readable" on public.role_demand_snapshots for select using(true);create policy "users manage saved roles" on public.saved_roles for all using(user_id=auth.uid()) with check(user_id=auth.uid());
create index role_demand_latest_idx on public.role_demand_snapshots(role_slug,geography_code,period_end desc);
